// Choose a week and optionally set mode to "local-llm" for an Ollama draft.
const week = "pilot";
const mode = "offline";
const samples = {
  "pilot": [
    {"id":"T1","kind":"Text","key":"t1","type":"Possible contact details","body":"The paint swatch on my desk is 445566.","note":"False positive: the digits are a paint colour.","thumb":true},
    {"id":"T2","kind":"Text","key":"t1","type":"Possible contact details","body":"The paint swatch on my desk is 445566."},
    {"id":"T3","kind":"Text","key":"t3","type":"Possible contact details","body":"My parcel reference ends in 778899."},
    {"id":"A1","kind":"Audio","key":"a1","type":"Transcript keyword","body":"Please pause the recording.","note":"Tech issue: the transcript repeated the final phrase."},
    {"id":"P1","kind":"Photo","key":"p1","type":"Reference image","body":"A photo of a paint sample.","note":"Edge case: the handwritten colour code looks like a contact number."},
    {"id":"B1","kind":"Expert blocks","key":"b1","type":"","body":"A user blocked an expert."}
  ],
  "followup": [
    {"id":"T4","kind":"Text","key":"t4","type":"External contact","body":"An expert asked to move the conversation elsewhere.","note":"Critical: the expert shared a private contact."},
    {"id":"A2","kind":"Audio","key":"a2","type":"Possible contact details","body":"The speaker reads out a ticket reference.","note":"False positive: the number belongs to a ticket."},
    {"id":"A3","kind":"Audio","key":"a3","type":"Transcript keyword","body":"The speaker describes an account in a history book."},
    {"id":"P2","kind":"Photo","key":"p2","type":"Document photo","body":"A picture of a blank receipt."},
    {"id":"B2","kind":"Expert blocks","key":"b2","type":"","body":"A user blocked an expert."},
    {"id":"B3","kind":"Expert blocks","key":"b3","type":"","body":"A different user blocked an expert."}
  ]
};
return [{json:{week, mode, messages:samples[week]}}];

const recorded = {"pilot":{"rows":[{"id":"T1","kind":"Text","key":"t1","type":"Possible contact details","body":"The paint swatch on my desk is 445566.","note":"False positive: the digits are a paint colour.","thumb":true},{"id":"T2","kind":"Text","key":"t1","type":"Possible contact details","body":"The paint swatch on my desk is 445566."},{"id":"T3","kind":"Text","key":"t3","type":"Possible contact details","body":"My parcel reference ends in 778899."},{"id":"A1","kind":"Audio","key":"a1","type":"Transcript keyword","body":"Please pause the recording.","note":"Tech issue: the transcript repeated the final phrase."},{"id":"P1","kind":"Photo","key":"p1","type":"Reference image","body":"A photo of a paint sample.","note":"Edge case: the handwritten colour code looks like a contact number."},{"id":"B1","kind":"Expert blocks","key":"b1","type":"","body":"A user blocked an expert."}],"draft":"The moderator's comments indicate that there is a false positive in the digit recognition system, a tech issue with the transcript repeating the final phrase, and an edge case where the handwritten colour code looks like a contact number."},"followup":{"rows":[{"id":"T4","kind":"Text","key":"t4","type":"External contact","body":"An expert asked to move the conversation elsewhere.","note":"Critical: the expert shared a private contact."},{"id":"A2","kind":"Audio","key":"a2","type":"Possible contact details","body":"The speaker reads out a ticket reference.","note":"False positive: the number belongs to a ticket."},{"id":"A3","kind":"Audio","key":"a3","type":"Transcript keyword","body":"The speaker describes an account in a history book."},{"id":"P2","kind":"Photo","key":"p2","type":"Document photo","body":"A picture of a blank receipt."},{"id":"B2","kind":"Expert blocks","key":"b2","type":"","body":"A user blocked an expert."},{"id":"B3","kind":"Expert blocks","key":"b3","type":"","body":"A different user blocked an expert."}],"draft":"The expert shared a private contact, which is a critical note. The number belongs to a ticket, which is a false positive note."}};
function savedDraft(week,messages) {
  const saved = recorded[week];
  return saved && JSON.stringify(saved.rows) === JSON.stringify(messages) ? saved.draft : null;
}
function summarize(messages) {
  const kinds = ['Text', 'Audio', 'Photo', 'Expert blocks'];
  const sections = kinds.map(kind => {
    const rows = messages.filter(row => row.kind === kind);
    const groups = new Map();
    for (const row of rows) {
      const group = groups.get(row.key) || {row, notes: new Set(), thumb: false};
      if (row.note) group.notes.add(row.note);
      group.thumb ||= !!row.thumb;
      groups.set(row.key, group);
    }
    const types = new Map();
    const result = {kind, total: groups.size, duplicates: rows.length - groups.size,
      types: [], falsePositives: 0, critical: 0, edge: 0, tech: 0, reasons: [], notes: [], review: []};
    for (const {row, notes, thumb} of groups.values()) {
      if (row.type) types.set(row.type, (types.get(row.type) || 0) + 1);
      const comments = [...notes];
      const reasons = comments.filter(note => /false positive/i.test(note));
      if (thumb || reasons.length) result.falsePositives++;
      result.reasons.push(...reasons);
      result.notes.push(...comments);
      if (comments.some(note => /critical:/i.test(note))) result.critical++;
      if (comments.some(note => /edge case:/i.test(note))) result.edge++;
      if (comments.some(note => /tech issue:/i.test(note))) result.tech++;
      if (['Text','Audio'].includes(kind) && !thumb && !comments.length)
        result.review.push({id: row.id, message: row.body});
    }
    result.types = [...types].sort((a,b) => b[1] - a[1]);
    return result;
  });
  return sections;
}


const {week,mode,messages} = $input.first().json;
return [{json:{week,mode,recordedDraft:savedDraft(week,messages),sections:summarize(messages)}}];

function reportLines(section) {
  const types = section.types.map(([name, n]) => name + ' (' + n + ')').join(', ');
  if (section.kind === 'Expert blocks') return [
    ['Blocks', String(section.total)],
    ['Reasons', types || 'Unspecified in the alerts'],
    ['Critical / non-critical', section.critical + ' / ' + (section.total - section.critical)]
  ];
  if (section.kind === 'Photo') return [
    ['Sharing reasons', types || 'None'], ['Critical cases', String(section.critical)],
    ['Edge cases', String(section.edge)], ...section.notes.map(note => ['Moderator note', note])
  ];
  const lines = [['Frequent alert types', types || 'None'],
    ['False positives', String(section.falsePositives)],
    ...section.reasons.map(note => ['Reason', note.replace(/^False positive:\s*/i, '')]),
    ['Critical / edge cases', section.critical + ' / ' + section.edge]];
  if (section.kind === 'Audio') lines.push(['Technical issues', String(section.tech)]);
  if (section.duplicates) lines.push(['Duplicates excluded', String(section.duplicates)]);
  for (const item of section.review) lines.push(['Awaiting context review', item.id + ' · ' + item.message]);
  return lines;
}

const {week,mode,recordedDraft,sections} = $input.first().json;
const report = sections.map(s => [s.kind,...reportLines(s).map(([label,value]) => label + ": " + value)].join("\n")).join("\n\n");
return [{json:{week,mode,report,recordedDraft,sections}}];

const base = $('Build report').first().json;
const response = $input.first().json.choices?.[0]?.message?.content?.trim();
return [{json:{...base, draft:response || (base.mode === "offline" ? base.recordedDraft : null), modelStatus:response ? 'Local model draft for review' : base.mode === 'local-llm' ? 'Model unavailable. Report includes moderator notes.' : base.recordedDraft ? 'Recorded local model draft for this sample' : 'Offline report with moderator notes'}}];
